import React, { useState, useEffect } from 'react';
import { 
  Container, Row, Col, Card, Table, Badge, Button, Form, 
  Alert // TAMBAHKAN INI
} from 'react-bootstrap'; // Pastikan Alert ada di sini
import { useApi } from '../contexts/ApiContext';
import { useNotification } from '../contexts/NotificationContext';

const LpsePage = () => {
  const [lpseData, setLpseData] = useState([]);
  const [filteredData, setFilteredData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filters, setFilters] = useState({
    kategori: '',
    provinsi: '',
    status: 'aktif'
  });
  const { showInfo } = useNotification();

  useEffect(() => {
    loadLpseData();
  }, []);

  useEffect(() => {
    filterLpseData();
  }, [filters, lpseData]);

  const loadLpseData = async () => {
    try {
      setLoading(true);
      // Simulate API call
      setTimeout(() => {
        const data = [
          {
            kode: 'pu',
            nama: 'Kementerian PU',
            kategori: 'kementerian',
            provinsi: 'DKI Jakarta',
            url_spse: 'https://spse.inaproc.id/pu',
            status: 'aktif',
            vendor_search: true,
            api_works: true,
            verified: true,
            years_supported: ['2023', '2024', '2025', '2026']
          },
          {
            kode: 'kemenkeu',
            nama: 'Kementerian Keuangan',
            kategori: 'kementerian',
            provinsi: 'DKI Jakarta',
            url_spse: 'https://spse.inaproc.id/kemenkeu',
            status: 'aktif',
            vendor_search: true,
            api_works: true,
            verified: true,
            years_supported: ['2023', '2024', '2025', '2026']
          },
          {
            kode: 'kemenperin',
            nama: 'Kementerian Perindustrian',
            kategori: 'kementerian',
            provinsi: 'DKI Jakarta',
            url_spse: 'https://spse.inaproc.id/kemenperin',
            status: 'aktif',
            vendor_search: true,
            api_works: true,
            verified: true,
            years_supported: ['2023', '2024', '2025', '2026']
          },
          {
            kode: 'pertanian',
            nama: 'Kementerian Pertanian',
            kategori: 'kementerian',
            provinsi: 'DKI Jakarta',
            url_spse: 'https://spse.inaproc.id/pertanian',
            status: 'aktif',
            vendor_search: true,
            api_works: true,
            verified: true,
            years_supported: ['2023', '2024', '2025', '2026']
          },
          {
            kode: 'jabarprov',
            nama: 'Pemerintah Provinsi Jawa Barat',
            kategori: 'pemerintah_provinsi',
            provinsi: 'Jawa Barat',
            url_spse: 'https://spse.inaproc.id/jabarprov',
            status: 'aktif',
            vendor_search: true,
            api_works: true,
            verified: true,
            years_supported: ['2023', '2024', '2025', '2026']
          },
          {
            kode: 'nasional',
            nama: 'SPSE Nasional',
            kategori: 'nasional',
            provinsi: 'Nasional',
            url_spse: 'https://spse.inaproc.id/nasional',
            status: 'aktif',
            vendor_search: true,
            api_works: true,
            verified: true,
            years_supported: ['2023', '2024', '2025', '2026']
          },
          {
            kode: 'jatengprov',
            nama: 'Pemerintah Provinsi Jawa Tengah',
            kategori: 'pemerintah_provinsi',
            provinsi: 'Jawa Tengah',
            url_spse: 'https://spse.inaproc.id/jatengprov',
            status: 'aktif',
            vendor_search: true,
            api_works: true,
            verified: true,
            years_supported: ['2023', '2024', '2025', '2026']
          },
          {
            kode: 'jatimprov',
            nama: 'Pemerintah Provinsi Jawa Timur',
            kategori: 'pemerintah_provinsi',
            provinsi: 'Jawa Timur',
            url_spse: 'https://spse.inaproc.id/jatimprov',
            status: 'aktif',
            vendor_search: true,
            api_works: true,
            verified: true,
            years_supported: ['2023', '2024', '2025', '2026']
          }
        ];
        setLpseData(data);
        setFilteredData(data);
        setLoading(false);
      }, 500);
    } catch (error) {
      console.error('Error loading LPSE data:', error);
      showInfo('Gagal memuat data LPSE');
      setLoading(false);
    }
  };

  const filterLpseData = () => {
    let filtered = [...lpseData];

    if (filters.kategori) {
      filtered = filtered.filter(lpse => lpse.kategori === filters.kategori);
    }

    if (filters.provinsi) {
      filtered = filtered.filter(lpse => lpse.provinsi === filters.provinsi);
    }

    if (filters.status) {
      filtered = filtered.filter(lpse => lpse.status === filters.status);
    }

    setFilteredData(filtered);
  };

  const handleFilterChange = (key, value) => {
    setFilters(prev => ({ ...prev, [key]: value }));
  };

  const resetFilters = () => {
    setFilters({
      kategori: '',
      provinsi: '',
      status: 'aktif'
    });
  };

  const getStatusBadge = (status) => {
    switch (status) {
      case 'aktif':
        return <Badge bg="success">Aktif</Badge>;
      case 'maintenance':
        return <Badge bg="warning">Maintenance</Badge>;
      default:
        return <Badge bg="secondary">{status}</Badge>;
    }
  };

  const getFeatureBadge = (feature, value) => {
    if (value) {
      return <Badge bg="success" className="me-1"><i className="fas fa-check"></i></Badge>;
    }
    return <Badge bg="danger" className="me-1"><i className="fas fa-times"></i></Badge>;
  };

  const getKategoriColor = (kategori) => {
    switch (kategori) {
      case 'kementerian':
        return 'primary';
      case 'pemerintah_provinsi':
        return 'success';
      case 'nasional':
        return 'info';
      default:
        return 'secondary';
    }
  };

  if (loading) {
    return (
      <Container className="py-5 text-center">
        <div className="spinner-border text-primary" role="status">
          <span className="visually-hidden">Loading...</span>
        </div>
        <p className="mt-3">Memuat data LPSE...</p>
      </Container>
    );
  }

  return (
    <Container className="py-4">
      {/* Header */}
      <div className="header-gradient mb-4 p-4 rounded" style={{
        background: 'linear-gradient(135deg, #6a11cb 0%, #2575fc 100%)',
        boxShadow: '0 10px 30px rgba(0,0,0,0.15)'
      }}>
        <Row className="align-items-center">
          <Col md={8}>
            <h1 className="display-6 fw-bold text-white mb-2">
              <i className="fas fa-server me-3"></i>Database LPSE Indonesia
            </h1>
            <p className="lead mb-0 text-white opacity-90">
              8 LPSE terintegrasi dengan support tahun 2023-2026
            </p>
          </Col>
          <Col md={4} className="text-md-end">
            <Badge bg="light" text="dark" className="fs-6">
              <i className="fas fa-database me-1"></i>
              {filteredData.length} LPSE
            </Badge>
          </Col>
        </Row>
      </div>

      {/* Stats Cards */}
      <Row className="mb-4">
        <Col md={3} className="mb-3">
          <Card className="border-0 shadow-sm h-100">
            <Card.Body className="text-center">
              <div className="dashboard-stats-number text-primary">
                {lpseData.length}
              </div>
              <Card.Title className="mt-2 mb-0">
                Total LPSE
              </Card.Title>
              <Card.Text className="text-muted small">
                Semua institusi
              </Card.Text>
            </Card.Body>
          </Card>
        </Col>
        
        <Col md={3} className="mb-3">
          <Card className="border-0 shadow-sm h-100">
            <Card.Body className="text-center">
              <div className="dashboard-stats-number text-success">
                {lpseData.filter(l => l.api_works).length}
              </div>
              <Card.Title className="mt-2 mb-0">
                API Aktif
              </Card.Title>
              <Card.Text className="text-muted small">
                Mendukung pencarian
              </Card.Text>
            </Card.Body>
          </Card>
        </Col>
        
        <Col md={3} className="mb-3">
          <Card className="border-0 shadow-sm h-100">
            <Card.Body className="text-center">
              <div className="dashboard-stats-number text-info">
                2026
              </div>
              <Card.Title className="mt-2 mb-0">
                Tahun Support
              </Card.Title>
              <Card.Text className="text-muted small">
                Data terbaru
              </Card.Text>
            </Card.Body>
          </Card>
        </Col>
        
        <Col md={3} className="mb-3">
          <Card className="border-0 shadow-sm h-100">
            <Card.Body className="text-center">
              <div className="dashboard-stats-number text-warning">
                {lpseData.filter(l => l.vendor_search).length}
              </div>
              <Card.Title className="mt-2 mb-0">
                Vendor Search
              </Card.Title>
              <Card.Text className="text-muted small">
                Mendukung cari vendor
              </Card.Text>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Filters */}
      <Card className="border-0 shadow-sm mb-4">
        <Card.Body>
          <Card.Title className="mb-3">
            <i className="fas fa-filter me-2"></i>Filter LPSE
          </Card.Title>
          <Row className="g-3">
            <Col md={4}>
              <Form.Group>
                <Form.Label>Kategori</Form.Label>
                <Form.Select
                  value={filters.kategori}
                  onChange={(e) => handleFilterChange('kategori', e.target.value)}
                >
                  <option value="">Semua Kategori</option>
                  <option value="kementerian">Kementerian</option>
                  <option value="pemerintah_provinsi">Pemerintah Provinsi</option>
                  <option value="nasional">Nasional</option>
                </Form.Select>
              </Form.Group>
            </Col>
            
            <Col md={4}>
              <Form.Group>
                <Form.Label>Provinsi</Form.Label>
                <Form.Select
                  value={filters.provinsi}
                  onChange={(e) => handleFilterChange('provinsi', e.target.value)}
                >
                  <option value="">Semua Provinsi</option>
                  <option value="DKI Jakarta">DKI Jakarta</option>
                  <option value="Jawa Barat">Jawa Barat</option>
                  <option value="Jawa Tengah">Jawa Tengah</option>
                  <option value="Jawa Timur">Jawa Timur</option>
                  <option value="Nasional">Nasional</option>
                </Form.Select>
              </Form.Group>
            </Col>
            
            <Col md={4}>
              <Form.Group>
                <Form.Label>Status</Form.Label>
                <Form.Select
                  value={filters.status}
                  onChange={(e) => handleFilterChange('status', e.target.value)}
                >
                  <option value="aktif">Aktif</option>
                  <option value="maintenance">Maintenance</option>
                  <option value="all">Semua Status</option>
                </Form.Select>
              </Form.Group>
            </Col>
          </Row>
          
          <div className="mt-3 d-flex justify-content-between">
            <div>
              <small className="text-muted">
                Menampilkan {filteredData.length} dari {lpseData.length} LPSE
              </small>
            </div>
            <div>
              <Button
                variant="outline-secondary"
                size="sm"
                onClick={resetFilters}
              >
                <i className="fas fa-redo me-1"></i>
                Reset Filter
              </Button>
            </div>
          </div>
        </Card.Body>
      </Card>

      {/* LPSE Table */}
      <Card className="border-0 shadow-sm">
        <Card.Body className="p-0">
          <div className="table-responsive">
            <Table hover className="mb-0">
              <thead className="table-light">
                <tr>
                  <th style={{ width: '8%' }}>Kode</th>
                  <th style={{ width: '25%' }}>Nama LPSE</th>
                  <th style={{ width: '15%' }}>Kategori</th>
                  <th style={{ width: '15%' }}>Provinsi</th>
                  <th style={{ width: '10%' }}>Status</th>
                  <th style={{ width: '12%' }}>Fitur</th>
                  <th style={{ width: '15%' }}>Aksi</th>
                </tr>
              </thead>
              <tbody>
                {filteredData.map((lpse) => (
                  <tr key={lpse.kode}>
                    <td>
                      <code className="text-primary fw-bold">{lpse.kode}</code>
                    </td>
                    <td>
                      <div className="fw-bold">{lpse.nama}</div>
                      <small className="text-muted">
                        <i className="fas fa-link me-1"></i>
                        <a 
                          href={lpse.url_spse} 
                          target="_blank" 
                          rel="noopener noreferrer"
                          className="text-decoration-none"
                        >
                          {lpse.url_spse}
                        </a>
                      </small>
                    </td>
                    <td>
                      <Badge bg={getKategoriColor(lpse.kategori)}>
                        {lpse.kategori}
                      </Badge>
                    </td>
                    <td>
                      <Badge bg="light" text="dark">
                        <i className="fas fa-map-marker-alt me-1"></i>
                        {lpse.provinsi}
                      </Badge>
                    </td>
                    <td>
                      {getStatusBadge(lpse.status)}
                      {lpse.verified && (
                        <Badge bg="info" className="ms-1">
                          <i className="fas fa-check-circle"></i>
                        </Badge>
                      )}
                    </td>
                    <td>
                      <div className="d-flex flex-column">
                        <small>
                          {getFeatureBadge('vendor_search', lpse.vendor_search)}
                          Cari Vendor
                        </small>
                        <small>
                          {getFeatureBadge('api_works', lpse.api_works)}
                          API Aktif
                        </small>
                        <small>
                          <Badge bg="light" text="dark" className="me-1">
                            {lpse.years_supported.length} tahun
                          </Badge>
                        </small>
                      </div>
                    </td>
                    <td>
                      <div className="d-flex gap-1">
                        <Button
                          size="sm"
                          variant="outline-primary"
                          href={`/vendor?mode=${lpse.kode}`}
                        >
                          <i className="fas fa-search me-1"></i>
                          Cari
                        </Button>
                        <Button
                          size="sm"
                          variant="outline-success"
                          href={lpse.url_spse}
                          target="_blank"
                        >
                          <i className="fas fa-external-link-alt me-1"></i>
                          Buka
                        </Button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </Table>
          </div>
        </Card.Body>
        
        <Card.Footer className="bg-light">
          <div className="d-flex justify-content-between align-items-center">
            <div>
              <Badge bg="primary" className="me-2">
                Kementerian: {lpseData.filter(l => l.kategori === 'kementerian').length}
              </Badge>
              <Badge bg="success" className="me-2">
                Provinsi: {lpseData.filter(l => l.kategori === 'pemerintah_provinsi').length}
              </Badge>
              <Badge bg="info">
                Nasional: {lpseData.filter(l => l.kategori === 'nasional').length}
              </Badge>
            </div>
            <small className="text-muted">
              Terakhir diperbarui: {new Date().toLocaleDateString('id-ID')}
            </small>
          </div>
        </Card.Footer>
      </Card>

      {/* Tips - GUNAKAN Alert YANG SUDAH DI IMPORT */}
      <Alert variant="info" className="mt-4">
        <h6><i className="fas fa-lightbulb me-2"></i>Tips Menggunakan LPSE:</h6>
        <ul className="mb-0">
          <li>Gunakan filter untuk mencari LPSE berdasarkan kategori atau provinsi</li>
          <li>LPSE dengan tanda centang hijau mendukung pencarian vendor</li>
          <li>Klik tombol "Cari" untuk langsung mencari di LPSE tersebut</li>
          <li>Data tahun 2026 tersedia di semua LPSE aktif</li>
          <li>LPSE dengan badge "Verified" sudah teruji dan stabil</li>
        </ul>
      </Alert>
    </Container>
  );
};

export default LpsePage;